```js
function makeSortable(ul){
  let active = null;

  const canStart = (e, li) => {
    if (e.pointerType === 'mouse') return true;
    return !!e.target.closest('.disc-handle');
  };

  ul.addEventListener('pointerdown', (e) => {
    if (active) return;
    const li = e.target.closest('.disc-item');
    if (!li || li.contains(document.activeElement) && document.activeElement === ul) {}
    if (!canStart(e, li)) return;
    if (e.button !== undefined && e.button !== 0) return;
    e.preventDefault();

    const startX = e.clientX, startY = e.clientY;
    let started = false;
    let ghost = null;

    const begin = (ev) => {
      const rect = li.getBoundingClientRect();
      ghost = li.cloneNode(true);
      ghost.classList.add('drag-ghost');
      ghost.style.width = rect.width + 'px';
      document.body.appendChild(ghost);
      li.classList.add('is-ghost-src');
      ul.classList.add('is-reordering');
      active = {
        li, ghost,
        offX: ev.clientX - rect.left,
        offY: ev.clientY - rect.top,
      };
      moveGhost(ev.clientX, ev.clientY);
    };

    const moveGhost = (x, y) => {
      ghost.style.transform = `translate(${x - active.offX}px, ${y - active.offY}px)`;
    };

    const place = (ev) => {
      const items = Array.from(ul.children).filter(x => x !== li);
      let ref = null;
      for (const it of items) {
        const r = it.getBoundingClientRect();
        if (ev.clientY < r.top + r.height / 2) { ref = it; break; }
      }
      const current = ref === null
        ? (ul.lastElementChild === li)
        : (li.previousElementSibling === ref);
      if (current) return;
      flipMove(() => ref ? ul.insertBefore(li, ref) : ul.appendChild(li));
    };

    const onMove = (ev) => {
      if (!started) {
        if (Math.hypot(ev.clientX - startX, ev.clientY - startY) < 5) return;
        started = true;
        begin(ev);
      }
      moveGhost(ev.clientX, ev.clientY);
      place(ev);
      autoScroll(ev);
    };

    const onUp = () => {
      cleanup();
      if (started) endDrag();
    };

    const cleanup = () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onCancel);
      if (ul) ul.classList.remove... (only if started)
    };
    ...
  });
}
```

Note: the `cleanup` before started: just remove listeners. If not started, no visual changes.

FLIP inside ul:

```js
function flipMove(mutate){
  const items = Array.from(ul.querySelectorAll('li'));
  const before = new Map(items.map(el => [el, el.getBoundingClientRect().top]));
  mutate();
  for (const el of items) {
    const dy = before.get(el) - el.getBoundingClientRect().top;
    if (Math.abs(dy) > .5) {
      el.style.transition = 'none';
      el.style.transform = `translateY(${dy}px)`;
      void el.offsetWidth;
      el.style.transition = '';
      el.style.transform = '';
    }
  }
  updateRanks(ul);
}
```

