// CDP functional test for the DISC clone
const WS_URL = process.argv[2];
const fs = require('fs');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

const ws = new WebSocket(WS_URL);
let idc = 0;
const pend = new Map();
const exceptions = [];
const consoleErrs = [];

const send = (method, params = {}) => new Promise((res, rej) => {
  const id = ++idc;
  pend.set(id, { res, rej });
  ws.send(JSON.stringify({ id, method, params }));
});

let opened = false;
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pend.has(m.id)) {
    const { res, rej } = pend.get(m.id);
    pend.delete(m.id);
    m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result);
    return;
  }
  if (m.method === 'Runtime.exceptionThrown') exceptions.push(JSON.stringify(m.params.exceptionDetails).slice(0, 300));
  if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') consoleErrs.push(JSON.stringify(m.params.args).slice(0, 200));
};

const ev = (expression) => send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  .then(r => { if (r.exceptionDetails) throw new Error('EVAL: ' + JSON.stringify(r.exceptionDetails).slice(0, 500)); return r.result.value; });

const mouse = (type, x, y, extra = {}) => send('Input.dispatchMouseEvent', Object.assign({ type, x: Math.round(x), y: Math.round(y), button: 'left', buttons: type === 'mouseMoved' || type === 'mouseReleased' ? undefined : 1, clickCount: 1 }, extra));

const touch = (type, pts) => send('Input.dispatchTouchEvent', { type, touchPoints: pts });

// ---- test data (from the original page) ----
const TEST = JSON.parse(fs.readFileSync('/tmp/test_data.json', 'utf-8'));
function expectedScore(overrides = []) {
  const maj = [], min = [];
  TEST.forEach((lists, s) => lists.forEach((items, l) => {
    let order = items.map(x => x[0]);
    const ov = overrides.find(o => o.s === s && o.l === l);
    if (ov) order = ov.order;
    maj.push(order[0]); min.push(order[3]);
  }));
  const count = (a, ch) => a.reduce((n, v) => n + (v === ch ? 1 : 0), 0);
  return {
    d: count(maj, 'd') - count(min, 'd'),
    i: count(maj, 'i') - count(min, 'i'),
    s: count(maj, 's') - count(min, 's'),
    c: count(maj, 'c') - count(min, 'c'),
  };
}
const fmt = (sc) => `D: ${sc.d}, I: ${sc.i}, S: ${sc.s}, C: ${sc.c}`;

let failures = 0;
const check = (name, actual, expected) => {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${ok ? '' : `\n   expected: ${JSON.stringify(expected)}\n   actual:   ${JSON.stringify(actual)}`}`);
};

ws.onopen = async () => {
  try {
    await send('Runtime.enable');
    await send('Page.enable');

    // ---------- 1. initial structure ----------
    const st = await ev(`(() => {
      const q = s => document.querySelector(s);
      const qa = s => [...document.querySelectorAll(s)];
      const tabs = qa('#tabs .disc-tab');
      const panes = qa('#bodyPane .disc-pane');
      const lists = qa('#bodyPane .disc-list');
      return {
        tabs: tabs.length,
        panes: panes.length,
        lists: lists.length,
        itemsPerList: lists.map(l => l.querySelectorAll('li').length),
        activePane: panes.findIndex(p => p.classList.contains('is-active')),
        modalOpen: q('#discModal').classList.contains('is-open'),
        progress: q('#discProgress').style.width,
        tabLabels: tabs.map(t => t.textContent),
        itemTypesL1: [...qa('#bodyPane .disc-pane.is-active .disc-list')[0].children].map(li => li.dataset.type),
      };
    })()`);
    check('initial structure: 8 tabs / 8 panes / 24 lists x4',
      [st.tabs, st.panes, st.lists, st.itemsPerList.every(n => n === 4), st.activePane, st.modalOpen, st.progress],
      [8, 8, 24, true, 0, false, '12.5%']);
    check('tab labels 1..8', st.tabLabels, ['1', '2', '3', '4', '5', '6', '7', '8']);
    check('list1 initial types', st.itemTypesL1, TEST[0][0].map(x => x[0]));
    check('initial score baseline', fmt(expectedScore()), fmt(expectedScore()));

    // ---------- 2. open modal ----------
    await ev(`document.querySelector('#openTest').click(); 1`);
    await sleep(80);
    const mopen = await ev(`(() => ({
      open: document.querySelector('#discModal').classList.contains('is-open'),
      aria: document.querySelector('#discModal').getAttribute('aria-hidden'),
      scroll: document.documentElement.classList.contains('no-scroll'),
    }))()`);
    check('modal opens + scroll lock', [mopen.open, mopen.aria, mopen.scroll], [true, 'false', true]);

    // ---------- 3. step navigation ----------
    await ev(`document.querySelector('#btnNext').click(); 1`);
    let nav = await ev(`(() => ({
      active: [...document.querySelectorAll('#bodyPane .disc-pane')].findIndex(p => p.classList.contains('is-active')),
      progress: document.querySelector('#discProgress').style.width,
      hint: document.querySelector('#stepHint').textContent,
      prevDisabled: document.querySelector('#btnPrev').disabled,
    }))()`);
    check('next -> step 2', [nav.active, nav.progress, nav.hint, nav.prevDisabled], [1, '25%', 'Шаг 2 из 8', false]);

    await ev(`document.querySelectorAll('#tabs .disc-tab')[7].click(); 1`);
    await sleep(50);
    nav = await ev(`(() => ({
      active: [...document.querySelectorAll('#bodyPane .disc-pane')].findIndex(p => p.classList.contains('is-active')),
      nextHidden: document.querySelector('#btnNext').hidden,
      finishHidden: document.querySelector('#btnFinish').hidden,
      progress: document.querySelector('#discProgress').style.width,
    }))()`);
    check('tab click -> step 8, finish visible', [nav.active, nav.nextHidden, nav.finishHidden, nav.progress], [7, true, false, '100%']);

    await ev(`document.querySelector('#btnPrev').click(); 1`);
    nav = await ev(`[...document.querySelectorAll('#bodyPane .disc-pane')].findIndex(p => p.classList.contains('is-active'))`);
    check('prev -> step 7', nav, 6);

    // ---------- 4. finish on untouched order ----------
    await ev(`document.querySelectorAll('#tabs .disc-tab')[7].click(); 1`);
    await ev(`document.querySelector('#btnFinish').click(); 1`);
    await sleep(120);
    let res = await ev(`(() => ({
      resultVisible: !document.querySelector('#resultView').hidden,
      testHidden: document.querySelector('#testView').hidden,
      score: document.querySelector('#scoreLine').innerText,
    }))()`);
    check('baseline result shown', [res.resultVisible, res.testHidden], [true, true]);
    check('baseline score value', res.score.replace(/\s+/g, ' ').trim(), fmt(expectedScore()));

    // ---------- 5. restart ----------
    await ev(`document.querySelector('#btnRestart').click(); 1`);
    await sleep(60);
    res = await ev(`(() => ({
      testVisible: !document.querySelector('#testView').hidden,
      resultHidden: document.querySelector('#resultView').hidden,
      activePane: [...document.querySelectorAll('#bodyPane .disc-pane')].findIndex(p => p.classList.contains('is-active')),
      l1: [...document.querySelectorAll('#bodyPane .disc-pane.is-active .disc-list')[0].children].map(li => li.dataset.type),
    }))()`);
    check('restart resets', [res.testVisible, res.resultHidden, res.activePane, res.l1], [true, true, 0, TEST[0][0].map(x => x[0])]);

    // ---------- 6. mouse drag: list1 item0 -> bottom ----------
    const drag = async (expr, fromSel, toSelIdx, useHandle) => {
      const info = await ev(`(() => {
        const li = document.querySelector('${fromSel}');
        const r = li.getBoundingClientRect();
        const target = [...document.querySelectorAll('${fromSel.startsWith('#drag') ? '' : fromSel.replace(/ li$/, '')} li')];
        return { x: r.left + (useHandle ? r.width - 20 : r.width / 2), y: r.top + r.height / 2, w: r.width, h: r.height,
                 targetRects: target.map(t => { const tr = t.getBoundingClientRect(); return { top: tr.top, height: tr.height }; }) };
      })()`);
      const sx = info.x, sy = info.y;
      // find the item (excluding dragged) whose midpoint we must pass / land below
      const others = info.targetRects.slice(); // will filter in js
      const liIdx = await ev(`[...document.querySelectorAll('${fromSel.replace(/ li$/, '')}')].length`); // not critical
      await mouse('mousePressed', sx, sy);
      let y = sy;
      // step past threshold
      await mouse('mouseMoved', sx + 2, y + 2);
      // determine end point: below midpoint of last *other* item
      const endY = await ev(`(() => {
        const li = document.querySelector('${fromSel}');
        const ul = li.parentElement;
        let lastMid = -1e9;
        for (const it of ul.children) { if (it === li) continue; const r = it.getBoundingClientRect(); lastMid = Math.max(lastMid, r.top + r.height / 2); }
        return lastMid + 30;
      })()`);
      while (y < endY - 4) {
        y = Math.min(y + 8, endY);
        await mouse('mouseMoved', sx + 3, y);
        await sleep(12);
      }
      await sleep(40);
      await mouse('mouseReleased', sx + 3, y);
      await sleep(80);
    };

    // generic: move item at data-idx in list N of active pane; identify li by position
    const listSel = (l) => `#bodyPane .disc-pane.is-active .disc-list:nth-child(${l + 1})` — wait, disc-list is inside disc-card inside grid. Let me fix selectors before running.
  } catch (e) {
    console.error('TEST ERROR:', e.message);
  }
};

