  if (m.id && pend.has(m.id)) {
    const { res, rej } = pend.get(m.id);
    pend.delete(m.id);
    m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result);
    return;
  }
  if (m.method === 'Runtime.exceptionThrown') exceptions.push(JSON.stringify(m.params.exceptionDetails).slice(0, 200));
  if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') consoleErrs.push(JSON.stringify(m.params.args).slice(0, 150));
};

const ev = (expression) => send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
