const mouse = (type, x, y, extra = {}) => send('Input.dispatchMouseEvent',
  Object.assign({ type, x: Math.round(x), y: Math.round(y), button: 'left', buttons: type === 'mousePressed' ? 1 : (type === 'mouseMoved' ? 1 : 0), clickCount: 1 }, extra));

const touch = (type, pts) => send('Input.dispatchTouchEvent', { type, touchPoints: pts.map(p => ({ x: Math.round(p.x), y: Math.round(p.y), id: 1 })) });

