async function dragMouse(l, fromIdx, toIdx) {
  // coords from page
  const info = await ev(`(() => {
    const li = document.querySelectorAll('${LIST_SEL(l)} li')[${fromIdx}];
    const r = li.getBoundingClientRect();
    return { sx: r.left + r.width / 2, sy: r.top + r.height / 2,
             width: r.width, items: [...li.parentElement.children].map(x => { const tr = x.getBoundingClientRect(); return x === li ? null : { top: tr.top, h: tr.height }; }) };
  })()`);
  const items = info.items.filter(Boolean); // other items
  // compute target pointer y
  let targetY;
  {
    // rebuild target order: remove li, insert at toIdx; find item that will precede (before) or that we pass midpoint of
    const others = items.map(o => o); // top->bottom order excluding dragged
    const targetOthers = others.slice();
    targetOthers.splice(Math.max(0, Math.min(targetOthers.length, toIdx)), 0, null);
    const beforeItem = targetOthers.slice(0, targetOthers.length).find(o => o !== null && targetOthers.indexOf(o) > targetOthers.indexOf(null));
    // simpler: scan from top; find first OTHER item whose midpoint is below the desired slot
    // desired slot = index toIdx among 4 items. If toIdx < otherCount, land above other item at position where it would be the (toIdx+1)-th item remaining... 
    // Easiest: simulate.
    let seq = others.slice();
    seq.splice(toIdx, 0, 'DRAG');
    // pointer must be: above midpoint of item AFTER DRAG (if any), and below midpoint of item BEFORE DRAG (if any)
    const afterItem = seq.slice(seq.indexOf('DRAG') + 1).find(x => x !== 'DRAG');
    const beforeItem2 = seq.slice(0, seq.indexOf('DRAG')).reverse().find(x => x && x !== 'DRAG');
    const ai = items.find(o => o === afterItem) ? items.indexOf(afterItem) : -1;
    const bi = items.findIndex(o => o === beforeItem2);
    targetY = (ai >= 0 ? items[ai].top + items[ai].h / 2 : (items.length ? items[items.length - 1].top + items[items.length - 1].h : 0)) - 12;
    if (bi >= 0) targetY = Math.max(targetY, items[bi].top + items[bi].h / 2 + 4);
  }
  await mouse('mousePressed', info.sx, info.sy);
  let cur = info.sy;
  await mouse('mouseMoved', info.sx + 2, info.sy + 2);
  while (Math.abs(cur - targetY) > 3) {
    cur += Math.sign(targetY - cur) * Math.min(7, Math.abs(targetY - cur));
    await mouse('mouseMoved', info.sx + 3, cur);
    await sleep(12);
  }
  await sleep(30);
  await mouse('mouseReleased', info.sx + 3, cur);
  await sleep(90);
}

async function dragTouch(l, fromIdx, toIdx, byHandle) {
  const info = await ev(`(() => {
    const li = document.querySelectorAll('${LIST_SEL(l)} li')[${fromIdx}];
    const r = li.getBoundingClientRect();
    const h = li.querySelector('.disc-handle').getBoundingClientRect();
    return { sx: r.left + r.width / 2, hx: h.left + h.width / 2, sy: r.top + r.height / 2,
             items: [...li.parentElement.children].map(x => { const tr = x.getBoundingClientRect(); return x === li ? null : { top: tr.top, h: tr.height }; }) };
  })()`);
  const items = info.items.filter(Boolean);
  let seq = items.slice();
  seq.splice(toIdx, 0, 'DRAG');
  const afterItem = seq.slice(seq.indexOf('DRAG') + 1).find(x => x !== 'DRAG');
  const beforeItem = seq.slice(0, seq.indexOf('DRAG')).reverse().find(x => x !== 'DRAG' && x !== undefined);
  let targetY;
  if (afterItem) {
    const ai = items.indexOf(afterItem);
    targetY = items[ai].top + items[ai].h / 2 - 10;
  } else {
    targetY = (items[items.length - 1] || { top: info.sy, h: 40 }).top + (items[items.length - 1] || { h: 40 }).h + 12;
  }
  if (beforeItem) {
    const bi = items.indexOf(beforeItem);
    targetY = Math.max(targetY, items[bi].top + items[bi].h / 2 + 6);
  }
  const sx = byHandle ? info.hx : info.sx;
  await touch('touchStart', [{ x: sx, y: info.sy }]);
  let cur = info.sy;
  await touch('touchMove', [{ x: sx + 2, y: info.sy + 3 }]);
  while (Math.abs(cur - targetY) > 3) {
    cur += Math.sign(targetY - cur) * Math.min(7, Math.abs(cur - targetY));
    await touch('touchMove', [{ x: sx + 2, y: cur }]);
    await sleep(12);
  }
  await sleep(30);
  await touch('touchEnd', []);
  await sleep(90);
}

