// instrumented single-drag probe
const WS_URL = process.argv[2];
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const ws = new WebSocket(WS_URL);
let idc = 0; const pend = new Map();
const send = (method, params = {}) => new Promise((res, rej) => { const id = ++idc; pend.set(id, {res, rej}); ws.send(JSON.stringify({id, method, params})); });
ws.onmessage = (ev) => { const m = JSON.parse(ev.data); if (m.id && pend.has(m.id)) { const {res, rej} = pend.get(m.id); pend.delete(m.id); m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result); } };
const ev = (expression) => send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }).then(r => r.result.value);
const mouse = (type, x, y) => send('Input.dispatchMouseEvent',
  { type, x: Math.round(x), y: Math.round(y), button: 'left', buttons: type === 'mouseReleased' ? 0 : 1, clickCount: 1 });

ws.onopen = async () => {
  // reset page
  await ev(`(() => { const r = document.querySelector('#btnRestart'); if (r && !document.querySelector('#testView').hidden) return 1; document.querySelector('#openTest').click(); return 0; })()`);
  await sleep(200);
  // ensure L1 = c,d,s,i as in the failing state (i at bottom)
  let t = await ev(`[...document.querySelectorAll('#bodyPane .disc-pane.is-active .disc-grid3 .disc-card:nth-of-type(1) .disc-list li')].map(li => li.dataset.type).join('')`);
  console.log('L1 start:', t);
  if (t !== 'cdsi') {
    // put i (idx3) to bottom if needed
    console.log('state: starting from different state; using as-is, target: move last item to index 0');
  }
  const liIdxToMove = 3; // i at bottom
  const info = await ev(`(() => {
    const li = document.querySelectorAll('#bodyPane .disc-pane.is-active .disc-grid3 .disc-card:nth-of-type(1) .disc-list li')[${liIdxToMove}];
    const r = li.getBoundingClientRect();
    return { sx: r.left + r.width / 2, sy: r.top + r.height / 2,
             items: [...li.parentElement.children].filter(x => x !== li).map(x => { const tr = x.getBoundingClientRect(); return { top: tr.top, h: tr.height, type: x.dataset.type, mid: tr.top + tr.height / 2 }; }) };
  })()`);
  console.log('items (others):', info.items);
  // target index 0 => pointer above midpoint of items[0]
  const targetY = info.items[0].mid - 12;
  console.log('start sy:', info.sy, 'targetY:', targetY);
  await mouse('mousePressed', info.sx, info.sy);
  const path = [];
  await mouse('mouseMoved', info.sx + 2, info.sy + 2);
  let cur = info.sy;
  while (Math.abs(cur - targetY) > 3) {
    cur += Math.sign(targetY - cur) * Math.min(7, Math.abs(targetY - cur));
    await mouse('mouseMoved', info.sx + 3, cur);
    path.push(Math.round(cur));
    await sleep(15);
  }
  await sleep(60);
  const orderBeforeRelease = await ev(`[...document.querySelectorAll('#bodyPane .disc-pane.is-active .disc-grid3 .disc-card:nth-of-type(1) .disc-list li')].map(li => li.dataset.type).join('')`);
  console.log('order before release:', orderBeforeRelease, ' final cur:', Math.round(cur));
  await mouse('mouseReleased', info.sx + 3, cur);
  await sleep(200);
  const orderAfter = await ev(`[...document.querySelectorAll('#bodyPane .disc-pane.is-active .disc-grid3 .disc-card:nth-of-type(1) .disc-list li')].map(li => li.dataset.type).join('')`);
  console.log('order after release:', orderAfter);
  console.log('path (last 8):', path.slice(-8));
  process.exit(0);
};
setTimeout(() => { console.error('TIMEOUT'); process.exit(1); }, 20000);

