e.preventDefault();
var startX = e.clientX, startY = e.clientY;
var started = false;
var ghost = null;
var dragId = {}; /* unique per pointerdown, protects the safety timer from grabbing a newer drag */

function beginDrag(ev) {
  var rect = li.getBoundingClientRect();
  ghost = li.cloneNode(true);
  ghost.classList.add('drag-ghost');
  ghost.style.width = rect.width + 'px';
  ghost.style.transform = 'translate(' + rect.left + 'px,' + rect.top + 'px)';
  document.body.appendChild(ghost);
  li.classList.add('is-ghost-src');
  ul.classList.add('is-reordering');
  active = { li: li, ghost: ghost, offX: ev.clientX - rect.left, offY: ev.clientY - rect.top, dragId: dragId };
}

function placeByPointer(ev) {
  var items = qsa('li', ul);
  var ref = null;
  for (var i = 0; i < items.length; i++) {
    if (items[i] === li) continue;
    var r = items[i].getBoundingClientRect();
    if (ev.clientY < r.top + r.height / 2) { ref = items[i]; break; }
  }
  var ok = ref === null
    ? ul.lastElementChild === li
    : li.previousElementSibling === ref;
  if (ok) return;
  flipMove(function () {
    if (ref) ul.insertBefore(li, ref); else ul.appendChild(li);
  });
}

function autoScroll(ev) {
  if (!scroller) return;
  var r = scroller.getBoundingClientRect();
  if (ev.clientY < r.top + 56) scroller.scrollTop -= 9;
  else if (ev.clientY > r.bottom - 56) scroller.scrollTop += 9;
}

function onMove(ev) {
  if (!ev.isPrimary) return;
  if (!started) {
    if (Math.hypot(ev.clientX - startX, ev.clientY - startY) < 5) return;
    started = true;
    beginDrag(ev);
    try { ghost.setPointerCapture(ev.pointerId); } catch (e2) {}
  }
  if (!active || active.dragId !== dragId) return;
  ghost.style.transform = 'translate(' + (ev.clientX - active.offX) + 'px,' + (ev.clientY - active.offY) + 'px)';
  placeByPointer(ev);
  autoScroll(ev);
}

function finish(commit) {
  window.removeEventListener('pointermove', onMove);
  window.removeEventListener('pointerup', onUp);
  window.removeEventListener('pointercancel', onCancel);
