    out.liHeights = [...new Set(lis.map(l => Math.round(l.getBoundingClientRect().height)))];
    out.overlap = (() => {
      let bad = 0;
      for (let i = 0; i < lis.length; i++) for (let j = i + 1; j < lis.length; j++) {
